CREATE OR REPLACE FUNCTION notify_companion_changed() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE changed_companion_id uuid; BEGIN IF TG_TABLE_NAME='companions' THEN changed_companion_id:=COALESCE(NEW.id,OLD.id); ELSE changed_companion_id:=COALESCE(NEW.companion_id,OLD.companion_id); END IF; PERFORM pg_notify('companion_changed',changed_companion_id::text); RETURN COALESCE(NEW,OLD); END; $$;
DO $$ DECLARE table_name text;trigger_name text; BEGIN FOREACH table_name IN ARRAY ARRAY['companions','runs','messages','task_questions','attachments'] LOOP trigger_name:=table_name||'_companion_changed'; IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgname=trigger_name AND tgrelid=table_name::regclass AND NOT tgisinternal) THEN EXECUTE format('CREATE TRIGGER %I AFTER INSERT OR UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION notify_companion_changed()',trigger_name,table_name); END IF; END LOOP; END; $$;
CREATE OR REPLACE FUNCTION notify_delegation_parent_changed() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN PERFORM pg_notify('companion_changed',COALESCE(NEW.parent_id,OLD.parent_id)::text); RETURN COALESCE(NEW,OLD); END; $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgname='delegations_parent_companion_changed' AND NOT tgisinternal) THEN CREATE TRIGGER delegations_parent_companion_changed AFTER INSERT OR UPDATE OR DELETE ON delegations FOR EACH ROW EXECUTE FUNCTION notify_delegation_parent_changed(); END IF; END; $$;
CREATE OR REPLACE FUNCTION notify_delegation_target_parents_changed() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN PERFORM pg_notify('companion_changed',d.parent_id::text) FROM delegations d WHERE d.target_id=COALESCE(NEW.id,OLD.id) AND d.finished_at IS NULL; RETURN COALESCE(NEW,OLD); END; $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgname='companions_delegation_parents_changed' AND NOT tgisinternal) THEN CREATE TRIGGER companions_delegation_parents_changed AFTER UPDATE OR DELETE ON companions FOR EACH ROW EXECUTE FUNCTION notify_delegation_target_parents_changed(); END IF; END; $$;
CREATE OR REPLACE FUNCTION notify_delegation_run_parent_changed() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN PERFORM pg_notify('companion_changed',d.parent_id::text) FROM delegations d WHERE d.run_id=COALESCE(NEW.id,OLD.id) AND d.finished_at IS NULL; RETURN COALESCE(NEW,OLD); END; $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgname='runs_delegation_parent_changed' AND NOT tgisinternal) THEN CREATE TRIGGER runs_delegation_parent_changed AFTER UPDATE OR DELETE ON runs FOR EACH ROW EXECUTE FUNCTION notify_delegation_run_parent_changed(); END IF; END; $$;
